        '  var _am = { exports: {} };\n' +
        '  (function(module, exports, require) {\n' + actionCode + '\n  })(\n' +
        '    _am, _am.exports,\n' +
        '    _shim\n' +
        '  );\n' +
        '  return _am.exports;\n' +
        '})()';

